"""Freeze seven observed screen paths and a bounded physical-context trial plan."""
from pathlib import Path
import hashlib,json,math,shutil
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[3]
W=ROOT/'level-editor/work/croisement02-refinement';B=W/'restart14-butterflies';O=B/'all7-context-plan-v1'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert shutil.disk_usage(ROOT).free>=10*1024**3,'10GiB floor'
O.mkdir(exist_ok=True)
a=json.loads((B/'source-audit-v1/report.json').read_text());mp=ROOT/'level-editor/library/scenes/croisement02.rhlos-map.json';m=json.loads(mp.read_text());lib=ROOT/'level-editor/library'
base=W/'source-states/covered.png';im=Image.open(base).convert('RGB');cos=math.cos(math.radians(35));rows=[]
sources={r['id']:r for r in m['assetSources']};candidates=[]
for p in m['placements']:
 t=p['transform'];assert t['rot_deg']==0
 r=sources[p['assets'][0]];dp=lib/r['descriptor'];d=json.loads(dp.read_text());pts=[]
 for part in d.get('parts',[]):
  for q in (part.get('obstacle_local_game') or {}).get('points',[]):
   for z in [q.get('z_bottom',0),q.get('z_top',0)]:pts.append((t['dx']+q['x'],t['dy']+q['y']-cos*(t['dz']+z),t['dz']+z))
 if pts:candidates.append({'id':p['id'],'model':r['model'],'model_sha256':r['model_sha256'],'descriptor_sha256':sha(dp),'projected_obstacle_bounds':[min(q[0] for q in pts),min(q[1] for q in pts),max(q[0] for q in pts),max(q[1] for q in pts)],'legacy_obstacle_height_range_not_mesh':[min(q[2] for q in pts),max(q[2] for q in pts)]})
colors=['#ff5353','#ffdd55','#64dcff','#f798ff','#77ff88','#ffa144','#c7a8ff']
for j,s in enumerate(a['sequences']):
 x,y,w,h=s['temporal_bbox'];box=(max(0,x-40),max(0,y-40),min(im.width,x+w+40),min(im.height,y+h+40));crop=im.crop(box);dr=ImageDraw.Draw(crop);path=[tuple(f['alpha_centroid_display']) for f in s['frames']]
 dr.line([(px-box[0],py-box[1]) for px,py in path],fill=colors[j],width=1)
 for k in [0,18,30,49,74,98]:
  px,py=path[k];dr.ellipse((px-box[0]-2,py-box[1]-2,px-box[0]+2,py-box[1]+2),outline='white');dr.text((px-box[0]+3,py-box[1]-3),str(k),fill='white')
 crop.resize((crop.width*3,crop.height*3),Image.Resampling.NEAREST).save(O/f'butterfly-{j+1:02d}-path-context.png')
 near=[c for c in candidates if c['projected_obstacle_bounds'][0]<box[2] and c['projected_obstacle_bounds'][2]>box[0] and c['projected_obstacle_bounds'][1]<box[3] and c['projected_obstacle_bounds'][3]>box[1]]
 for f in s['frames']:assert sha(Path(f['source']))==f['sha256']
 rows.append({'index':s['index'],'profile':s['profile'],'sprite':s['sprite'],'observed_count':1,'frames':99,'ticks':198,'seconds_at25hz':7.92,'empty_frames':s['empty_frames'],'temporal_bbox':s['temporal_bbox'],'path': [{'phase':f['index'],'first_tick':f['first_tick'],'duration_ticks':f['duration_ticks'],'bbox':f['bbox'],'alpha_centroid_display':f['alpha_centroid_display'],'source':f['source'],'sha256':f['sha256']} for f in s['frames']], 'broadphase_context':near,'context_warning':'Projected obstacle bounds are coarse candidate selection only; they omit scenery-only receivers; legacy obstacle heights are not refined mesh heights. Hidden state placements require active-state filtering. These bounds do not establish actual visibility/contact.','depth_status':'UNRESOLVED: no height derived from display elevation or centroid.','native_background_fx':s['sprite']['elevation']==0})
fitp=B/'rig-joint-trial-v1/fit.json';fit=json.loads(fitp.read_text())
report={'status':'PRIVATE_PLAN_NO_MODEL_PROPAGATION','map_sha256':sha(mp),'base_art_sha256':sha(base),'source_audit_sha256':sha(B/'source-audit-v1/report.json'),'sequences':rows,'behavior':{'clock':'99 source frames held exactly two25Hz ticks,198tick cyclic clock; no invented interpolation.','ordering':'Elevated ambient effects sorted by display polyline minimumY, merged relative to actors by polyline-side test. This is ordering metadata, not a physical altitude.','masking':'Ordinary FX sprite creation leaves default masking disabled; masked-FX is a distinct path. Native sprite visibility cannot be converted blindly into geometric collision constraints.','zero_elevation':'Butterfly05 is blitted to background and captures/restores the previous background; disabled/empty-frame restoration remains a separate contract. All currently exported frames are nonempty.','appearance':'Own baked sprite colors remain evidence; source phase color variation has not established separate upper/lower material identities.'},'next_context_trial':{'scope':'One representative per each of three screen clusters, plus butterfly05 separately; no seven-model propagation.','inputs':'Use exact installed map pins and selected nearby GLB geometry including scenery-only nodes, not only obstacle bounds. Stream selected geometry; no scene copy.','procedure':['Extract native-ray visible depth and ground/bank surfaces beneath observed source paths; preserve node world transforms and alpha-aware receivers.','Evaluate constant-height hypotheses plus minimum smooth height changes constrained to maintain source screen anchor. Each height changes worldY by -cot(35)*height; compare all99 center positions and complete wing extents against geometry.','Reject solid intersections and report native visibility differences explicitly rather than raising all effects above trees. Native background05 may require a distinct source-behavior visibility policy; physical hypothesis cannot silently redefine it.','Render only bounded cluster context at native and opposite views for extreme path phases after geometry extraction/root agreement.'],'inferred':'Flight height, hidden depth, body registration separate from wing-dependent centroid, wing-side pattern and inter-effect phase offsets unless serialized evidence supports them.','budget':'CPU plan under8MiB; subsequent selected extraction must use FIFO2threads if Blender,10GiB free floor.'},'phase30_trial':{'status':'PROPOSED_ONLY','frozen_fit_sha256':sha(fitp),'change_only_phase':30,'neighbors_frozen':[29,31],'all_other_98_poses_exact':True,'source_evidence_phases':[28,29,30,31,32],'hypothesis':'Current30 retains near-symmetric hinges from29 although source has left low lobe and right raised lobe. Test independent left/right hinge opening and small body roll; do not interpret brown fringe as an extra wing.','search_bounds_relative_current':{'left_hinge_degrees':[-25,25],'right_hinge_degrees':[-25,25],'body_roll_degrees':[-12,12],'body_pitch_yaw':'frozen first pass','registration_pixels':[-0.75,0.75]},'selection':'Separate left/right projected wing-tip heights, projected body axis and warm body anchor; source silhouette secondary. Enforce quaternion/hinge continuity against frozen29/31, compare both wing-label assignments, retain ambiguity if tied.','material':'Existing fixed UV/image and conserved anatomy exact; no per-phase texture/brightness changes.','proof':'At most three CPU candidates; choose one for saved phase30 native/rear+actual8/solid8 after root review. Report source coverage and continuity deltas, not exact color parity.'}}
(O/'plan.json').write_text(json.dumps(report,indent=2)+'\n')
assert sum(p.stat().st_size for p in O.iterdir())<8*1024**2
print(json.dumps({'output':str(O),'bytes':sum(p.stat().st_size for p in O.iterdir()),'scene_candidates':[(r['profile'],len(r['broadphase_context'])) for r in rows]},indent=2))
